private val mutex = Mutex()
private val cache = mutableMapOf<Key, Value>()

suspend fun snapshot(): Map<Key, Value> = mutex.withLock { cache.toMap() }

suspend fun put(key: Key, value: Value) = mutex.withLock {
    cache[key] = value
}

